head.b:skin:
	/*
-----------------------------------------------
Blogger Template Style
Name:     Typography Clean & Minimal Blogger Template
Version : Premium Version
----------------------------------------------- */

/* Variable definitions
-----------------------
<Variable name="color.theme" description="Tema de color" type="color" default="#c62641" value="#c62641"/>

<Group description="Texto de la página" selector="">
<Variable name="body.font" description="Fuente" type="font" default="normal normal 14px Domine" value="normal normal 14px Domine"/>
<Variable name="body.text.color" description="Color del texto" type="color" default="#444444" value="#444444"/>
<Variable name="body.link.color" description="Color del enlace" type="color" default="#c62641" value="#c62641"/>
<Variable name="body.link.color.hover" description="Color al pasar el cursor" type="color" default="#000000" value="#000000"/>
</Group>
<Group description="Títulos de las entradas" selector="">
<Variable name="post.title.font" description="Fuente" type="font" default="35px Josefin Sans" value="35px Josefin Sans"/>
<Variable name="post.title.color" description="Color" type="color" default="#333333"  value="#333333"/>
<Variable name="post.title.color.hover" description="Color al pasar el cursor" type="color" default="#c62641"  value="#c62641"/>
</Group>
<Group description="Navegación" selector="">
<Variable name="navbar.text.font" description="Fuente de la barra de navegación" type="font" default="11px Josefin Sans" value="11px Josefin Sans"/>
<Variable name="navbar.text.color" description="Color del texto de la barra de navegación" type="color" default="#ffffff" value="#ffffff"/>
</Group>

-----------------------
*/

a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;border:0;outline:0;vertical-align:baseline;background:0 0;margin:0}
ins{text-decoration:underline}
del{text-decoration:line-through}
dl,ul{list-style-position:inside;font-weight:700;list-style:none;}
ul li{list-style:none}
caption,th{text-align:center}
img{border:none;position:relative}
.clear{clear:both}
.section,.widget,.widget ul{margin:0;padding:0}
h1,h2,h3,h4,h5,h6{padding:0;margin:0}
a:link,a:visited{color:$(body.link.color);;text-decoration:none}
a:hover{color:$(body.link.color.hover)}
:focus{outline:0}
a img{border:0}
#navbar-iframe{display:none;height:0;visibility:hidden}
span.item-control,a.quickedit{display:none!important}
body{background:#f8f8f8; color: $(body.text.color);
  font:$(body.font);font-weight: 400;line-height:22px;padding:0;word-wrap:break-word;  }
*{outline:0;transition:all .3s ease;-webkit-transition:all .3s ease;-moz-transition:all .3s ease;-o-transition:all .3s ease}
code{padding:2px 4px;font-size:90%;color:#c7254e;background-color:#f9f2f4;border-radius:4px}
.archive .home-link,.index .home-link{display:none}
.uk-post-title,h2.post-title,h3.wrp-titulo,.PopularPosts ul li a,.item .post-title,.static_page .post-title,.related-title a,.cmmwidget a,ul.post-nav span,.comments h4,.comments .comments-content .comment-header a,ul.post-nav{font-family:'Domine',sans-serif}
p.recent-des,.resumo span,.resumo a,.item .post-body,.static_page .post-body{   
    font-family: 'Domine';
 }
.status-msg-body{font-size:13px}
.status-msg-wrap{font-size:13px;margin:0 auto 25px}
.status-msg-border{border:1px solid #f0f0f0;opacity:1}
.status-msg-bg{background-color:#fff}
.status-msg-wrap a:hover{text-decoration:underline}
#outer-wrapper{    max-width: 1170px;
    margin: 100px auto 0;
    background-color: #FFF;
    z-index: 999;
    position: relative;    -webkit-box-shadow: 0 30px 50px 0 rgba(1,1,1,.15);
    box-shadow: 0 30px 50px 0 rgba(1,1,1,.15);}
.row{width:1150px}
#topnav{width:100%;height:36px;background-color:#262626;margin:0}
.tm-head{margin:0 auto;height:36px;line-height:36px}
.tm-menu{float:left;height:30px}
#nav1 li{float:left;display:inline-block;line-height:36px;padding:0;margin-right:15px}
#nav1 li a{     margin-right: 10px;

    position: relative;
    display: inline-block;

    -webkit-transition: all 0.35s ease-in-out;
    -moz-transition: all 0.35s ease-in-out;
    -ms-transition: all 0.35s ease-in-out;
    -o-transition: all 0.35s ease-in-out;
    transition: all 0.35s ease-in-out;

    color: #CCC;

    font-weight: 100;
    text-transform: uppercase;
    font-size: 11px;
    font-family: 'Open Sans', sans-serif;}

ul#nav1 li a:before {
    content: "";
    position: absolute;
    left: 100%;
    bottom: 35%;
    height: 30%;
    width: 1px;
    border-right: 1px solid rgba(255, 255, 255, .2);
    -webkit-border-radius: 20px;
    -moz-border-radius: 20px;
    border-radius: 20px;
    margin-left: 11px;
}

ul#nav1 li:last-child a:before{
display:none;
}

#sb-site {
    width: 100%;
    height: 330px;
    background: $(color.theme);
    position: absolute;
    z-index: 9;
}
#nav1 li a:hover,.tn-head #social-top ul li a:hover{color:$(color.theme)}
.tm-menu ul li a .fa{margin-right:5px}
.tn-right{float:right;height:80px}
.social-area{float:left;    margin-right: 15px;}
.tm-head #social-top{position:relative;display:block;margin-right:0}
.tm-head #social-top ul{overflow:hidden}
.tm-head #social-top ul li{line-height:90px;display:block;float:left;margin-left:15px;padding:0}
.tm-head #social-top ul li a{    display: block;
    float: left;
    text-decoration: none;

    color: #fff;

    font-weight: 100;
    text-transform: uppercase;
    font-size: 13x;}
.tm-head #social-top ul li a:before{display:inline-block;font-family:FontAwesome;font-style:normal;font-weight:400;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
.tm-head #social-top ul li a:hover{color:$(color.theme)}
#social-top .facebook:before{content:"\f09a"}
#social-top .bloglovin:before{content:"\f004"}
#social-top .twitter:before{content:"\f099"}
#social-top .gplus:before{content:"\f0d5"}
#social-top .rss:before{content:"\f09e"}
#social-top .vimeo:before{content:"\f27d"}
#social-top .youtube:before{content:"\f167"}
#social-top .skype:before{content:"\f17e"}
#social-top .stumbleupon:before{content:"\f1a4"}
#social-top .tumblr:before{content:"\f173"}
#social-top .vine:before{content:"\f1ca"}
#social-top .stack-overflow:before{content:"\f16c"}
#social-top .linkedin:before{content:"\f0e1"}
#social-top .dribbble:before{content:"\f17d"}
#social-top .soundcloud:before{content:"\f1be"}
#social-top .behance:before{content:"\f1b4"}
#social-top .digg:before{content:"\f1a6"}
#social-top .instagram:before{content:"\f16d"}
#social-top .pinterest:before{content:"\f0d2"}
#social-top .delicious:before{content:"\f1a5"}
#social-top .codepen:before{content:"\f1cb"}
.uk-search-header{    position: relative;
    height: 36px;
    margin: 0;
    padding-left: 20px;
    border-left: 1px solid #f0f0f0;
    font-size: 12px;
    float: right;
    margin-left: 10px;
    background: #fff;}
.uk-search-header .fa-search{    color: #aaa;
    position: absolute;
    line-height: 36px;
    font-size: 17px;}
.uk-search-header .uk-searchbox-header{height: 36px;
    border: 0;
    background-color: transparent;
    padding-left: 24px;
    font-size: 12px;
    color: #000;}
#header-blog{    position: relative;
    width: auto;
    float: left;
    height: 80px;
    margin-right: 50px;}
.header-content{margin:0 auto;overflow:hidden}
.header-logo img{height:auto;margin:26px 0 0;max-width:100%;}
.Header h1{    margin-bottom: 0px;
    margin-top: 0px;
    font-size: 30px;
    height: 80px;
    line-height: 80px;
    color: #ffffff;
    font-size: 28px;
    font-family: 'Josefin Sans';
    font-weight: 600;}
.Header h1 a {
    color: #fff;
}
.header-ads{width:729px;max-width:100%;max-height:90px;float:right;margin:0}
#ads-content .widget h2{display:none}
#header-navigation{margin:0 auto;top:0;height:80px;    background: $(color.theme);
    border: 0;    z-index: 99999;
    position: relative;
    }

.pattern.foooter svg {
    fill: #222;
    margin-bottom: -7px;
}

.nav-wrapper{font-family:'Montserrat',sans-serif;   
    margin: 0 auto;
    box-sizing: border-box;
    height: 80px;
}
.header-menu li.home-child{float:left;height:80px;display:inline-block;padding:0;margin-right:1px;width:80px;text-align:center;}
.header-menu li.home-child a{height:80px;line-height:51px;font-size:22px;font-weight:400;color:#FFF}
.header-menu li.home-child a:before{content:'\f015';display:inline-block;font-family:FontAwesome;font-style:normal;font-weight:400;line-height:normal}
.header-menu li.home-child:hover{}
#menu{display:none}
#menu ul li{float:left;height:80px;display:inline-block;padding:0;margin-right:1px;transition:all .3s ease-out!important;-webkit-transition:all .3s ease-out!important;-moz-transition:all .3s ease-out!important;-o-transition:all .3s ease-out!important;    
}

#menu ul li:hover a{color:#fff}
#menu ul li a{    
    padding: 12px;
    transition: all .3s ease-out!important;
    -webkit-transition: all .3s ease-out!important;
    -moz-transition: all .3s ease-out!important;
    -o-transition: all .3s ease-out!important;

    text-transform: uppercase;
    letter-spacing: 0px;
font:$(navbar.text.font);

	color:$(navbar.text.color); height: 80px;    font-weight: 700;
    line-height: 80px;  -webkit-transition: all .1s ease-in-out;
    -moz-transition: all .1s ease-in-out;
    -ms-transition: all .1s ease-in-out;
    -o-transition: all .1s ease-in-out;
    transition: all .1s ease-in-out;
    -webkit-backface-visibility: hidden;}
#menu ul > li > a .fa{margin-right:8px}
#menu ul li.hasSub a:after{margin-left:8px;margin-top:0px;position:relative;display:inline-block;content:'\f107';font-family:FontAwesome;font-weight:400;font-size:11px;text-rendering:auto;transition:all .3s ease-out!important;-webkit-transition:all .3s ease-out!important;-moz-transition:all .3s ease-out!important;-o-transition:all .3s ease-out!important}
#menu ul li.hasSub ul li a:after{display:none!important}
#menu ul li:hover ul{left:auto;z-index:9999}
#menu ul li ul{position:absolute;left:-9999px;z-index:9999;width:170px;margin:0;padding:0;box-shadow:0 1px 3px rgba(0,0,0,.3)}
#menu ul li ul li{background-color:#fff;float:none!important;display:block;padding:0;margin-right:0;height:auto}
#menu ul li ul li:hover{background-color:#000}
#menu ul li ul#sub-menu li a{
       line-height: 36px;
    text-decoration: none;
    height: auto;
    padding: 12px;
    color: #000;
    transition: all .3s ease-out!important;
    -webkit-transition: all .3s ease-out!important;
    -moz-transition: all .3s ease-out!important;
    -o-transition: all .3s ease-out!important;

    text-transform: uppercase;
    letter-spacing: 0px;
    font-size: 11px;
    font-family: 'Josefin Sans';}
#menu ul li ul#sub-menu li:hover a{color:#FFF!important}
#menu ul li ul li:hover a{color:$(color.theme)!important}
#menu ul li,#menu ul li ul,#menu ul li a,#menu ul li ul#sub-menu li a i{outline:0;transition:all 0s ease!important;-webkit-transition:all 0s ease!important;-moz-transition:all 0s ease!important;-o-transition:all 0s ease!important}
#menu ul li a:hover {
    background: rgba(255,255,255,.1);
    -webkit-box-shadow: 0 10px 15px 0 rgba(0,0,0,.15);
    box-shadow: 0 10px 15px 0 rgba(0,0,0,.15);
}

.selectnav{display:none}
#selectnav1{margin-top:10px}
select.selectnav{color:#fff;padding:6px 5px 5px;border:0;background-color:rgba(255,255,255,.1);font:14px Roboto,sans-serif;cursor:pointer;width:100%;height:30px;-webkit-appearance: none;}
select#selectnav1 option {
    background: #333;
}
.header-random{position:relative;float:right}
.header-random li{list-style:none}
.header-random a.rdn-icon{-webkit-transition:all .3s ease-out 0;-moz-transition:all .3s ease-out 0;transition:all .3s ease-out 0;cursor:pointer;display:block;height:80px;text-align:center;position:relative;right:0;width:30px;border-radius:0}
.header-random a.rdn-icon:before{color:#fff;content:'\f074';font-family:FontAwesome;font-size:16px;text-rendering:auto;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;line-height:90px}
#content-wrapper{margin:40px auto;overflow:hidden}
.error_page #main-wrapper{width:100%!important;margin:0!important}
.error_page .sidebar-wrapper,.error_page .status-msg-wrap{display:none}
#error-wrap{color:$(color.theme);text-align:center;padding:60px 0 80px}
.error-item{font-size:160px;line-height:1;margin-bottom:20px}
#error-wrap h2{font-size:25px;padding:20px 0 10px}
#error-wrap .homepage{padding-top:10px;display:block}
#error-wrap .homepage i{font-size:20px}
#error-wrap .homepage:hover{text-decoration:underline}
#main-wrapper{   
    width: 728px;
    word-wrap: break-word;
    margin: 0 auto;    padding:100px 0;}
#feat-sec h2,#feat-sec .widget-content{display:none}
div#feat-sec h2.title {
    display: none!important;
}

.index article.my-wrapz {
    position: relative;
    padding-left: 140px;
}
.date-header {
    position: inherit!important;
}

.box-title h2{    text-transform: uppercase;
    color: #333333;
    font-size: 1.5rem;
    text-align: center;
    font-family: 'Josefin Sans';font-size: 15px;}
.box-title h2 a{color:#222}

.box-title h2:after{    content: "";
    height: 1px;
    width: 50px;
    position: absolute;
    bottom: 0;
    left: 50%;
    margin-left: -25px;
    background: #333;
    background: rgba(51,51,51,0.2);

}
.uk-featured-post{overflow:hidden;display:block;margin-bottom:25px}
.uk-featured-post .uk-column1{float:left;width:50%;box-sizing:border-box;padding-right:20px}
.uk-featured-post .uk-column2{float: left;
    width: 24.13%;
    padding-right: 20px;}
.uk-column2.tooo {
    padding-right: 0px!important;
}
.uk-featured-post .uk-column2 .item2{margin-bottom:15px}
.uk-featured-item{overflow:hidden;position:relative;padding:0}
.uk-post-thumb{width:100%;height:150px;display:block;overflow:hidden;position:relative}
.uk-post-thumb .uk-image{display:block;height:150px;overflow:hidden}
.uk-column1 .uk-post-thumb,.uk-column1 .uk-post-thumb .uk-image{height:308px}
.uk-post-caption{position:relative;width:100%;padding:10px 0 0;box-sizing:border-box}
.uk-column1 .uk-post-caption{padding:18px 0 0}
.uk-post-title{    margin-bottom: 5px;
    font-size: 16px;
    line-height: 22px;
    font-family: 'Montserrat';
    font-weight: 700;
    letter-spacing: -0.4px;
    margin: 0 0 5px;}
.uk-column1 .uk-post-title{    font-size: 22px;
    font-family: 'Montserrat';
    line-height: 28px;
    font-weight: 700;
    letter-spacing: -0.4px;
    margin: 0 0 5px;}
.uk-post-title a{color:#222}
.uk-post-title a:hover{color:$(color.theme)}
.uk-post-meta{font-weight:400;display:inline-block}
.uk-snippet span{margin-top: 0;
    color: #666666;
    font-size: 13px;
    line-height: 22px;
    margin: 0 0 10px;
    font-family: 'Open Sans',sans-serif;}
.uk-post-meta span{float:left;    padding: 0;
    margin: 0;
    font-family: 'Montserrat', sans-serif;
    display: inline-block;
    font-size: 10px;
    text-transform: uppercase;
    color: #666;}
.uk-column1 .uk-post-meta span{font-size:11px;line-height:1.3em}
.uk-post-meta span strong{color:#222}
.uk-post-meta span:after{content:"-";margin:0 8px}
.uk-post-meta span.uk-date:after{display:none}
.uk-column1 .meta-border{margin:3px 0 8px}

.uk-post-thumb > a:before {
    position: absolute;
    content: '';
    width: 100%;
    height: 100%;
    background-color: #000;
    opacity: 0;
    left: 0;
    top: 0;
    -webkit-transition: all 0.35s ease-in-out;
    -moz-transition: all 0.35s ease-in-out;
    -ms-transition: all 0.35s ease-in-out;
    -o-transition: all 0.35s ease-in-out;
    transition: all 0.35s ease-in-out;
}

.uk-post-thumb:hover > a:before {
    opacity: 0.3;
}

.mvp-feat-gal-but {
    -webkit-border-radius: 50%;
    -moz-border-radius: 50%;
    -ms-border-radius: 50%;
    -o-border-radius: 50%;
    border-radius: 50%;
    position: absolute;
    right: 20px;
    top: 20px;
    width: 40px;
    height: 40px;
    background: $(color.theme);

}
.mvp-feat-gal-but i {
    -webkit-backface-visibility: hidden;
    color: #fff;
    font-size: 18px;
    margin: -9px 0 0 -9px;
    position: absolute;
    top: 50%;
    left: 50%;
}

i.vide {
    -webkit-backface-visibility: hidden;
    color: #fff;
    font-size: 22px;
    margin: -26.66666666% 0 0 -16.66666666%;
    position: absolute;
    top: 50%;
    left: 50%;
}
ul.roma-widget li {
    padding: 0!important;
}

ul.roma-widget {
    border: 1px solid #eee;
}

.roma-widget1 .wid-thumb {
    width: 100px;
    height: 100px;
    float: left;
    margin-right: 10px;
    overflow: hidden;
}
.p-date {
    color: #aaa;
    font-weight: 400;
    font-size: 11px;
}
.roma-widget1 .mag-thumb{display:block;    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;}
.roma-widget1 .wrp-titulo{font:normal normal 15px;margin:0 0 3px;overflow:hidden}
.roma-widget1 .wrp-titulo a{color:#222;    font-size: 13px!important;
    font-family: 'Montserrat';
    font-weight: 700;
    letter-spacing: -0.4px;
    line-height: 18px;}
.roma-widget1 .wrp-titulo a:hover{color:$(color.theme)}

.sect-left .roma-widget1 .wrp-titulo a{color:#fff}
.footer-column .roma-widget1 li{overflow:hidden;padding:10px 0}
.sect-left .roma-widget1 li{overflow:hidden;padding:10px 0}

.sect-left .roma-widget1 .wrp-titulo a:hover{color:$(color.theme)}

#ads-home{width:728px;max-width:100%;max-height:90px;margin:0 auto 25px;overflow:hidden}
#ads-home .widget{line-height:0}
#ads-home .widget h2{display:none}
#ads-top h2{display:none}
#ads-top .widget-content{width:970px;max-height:90px;margin:30px auto 20px;padding:0;    text-align: center;}
.post{display:block;word-wrap:break-word}

.index .post,.archive .post{    margin-bottom: 90px;
    padding-bottom: 100px}
.index .post-outer:nth-of-type(1) .post{padding-top:0}
.block-image{    float: left;
    width: 400px;
    height: 240px;
    position: relative;
    margin-right: 20px;}
.block-image .thumb{    width: 100%;
    height: 240px;
    position: relative;
    display: block;
    z-index: 2;
    overflow: hidden;}
.block-image .thumb a{width:100%;display:block;height:240px}

.block-image .thumb > a:before {
    position: absolute;
    content: '';
    width: 100%;
    height: 100%;
    background-color: #000;
    opacity: 0;
    left: 0;
    top: 0;
    -webkit-transition: all 0.35s ease-in-out;
    -moz-transition: all 0.35s ease-in-out;
    -ms-transition: all 0.35s ease-in-out;
    -o-transition: all 0.35s ease-in-out;
    transition: all 0.35s ease-in-out;
}

.block-image .thumb:hover > a:before {
    opacity: 0.3;
}

.postags{position:absolute;top:15px;left:15px;z-index:3}
.postags a{
    background: $(color.theme);
    color: #fff;
    margin: 0;
    font-family: 'Montserrat', sans-serif;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding: 4px 5px 3px;}
.postags a{display:none}
.postags a:first-child{display:inline-block}
.postags a:hover{background:#aaa}

abbr.published.timeago {
    position: relative;
    display: inline-block;
    font-size: 11px;
    font-weight: 300;
    text-transform: uppercase;
    font-family: 'Montserrat', sans-serif;
    color: #B7B7B7;
}

.post-outer:nth-child(1) .postags a {
    background-color: #ff3c36 !important;
    color: #fff !important;
}

.post-outer:nth-child(2) .postags a {
    background-color: #000000 !important;
    color: #fff !important;
}
.post-outer:nth-child(3) .postags a {
    background-color: #19dada !important;
    color: #fff !important;
}
.post-outer:nth-child(4) .postags a {
    background-color: #358FE7 !important;
    color: #fff !important;
}
.post-outer:nth-child(5) .postags a {
    background-color: #82A805 !important;
    color: #fff !important;
}
.post-outer:nth-child(6) .postags a {
    background-color: #f80029 !important;
    color: #fff !important;
}
.post-outer:nth-child(7) .postags a {
    background-color: #000000 !important;
    color: #fff !important;
}
.post-outer:nth-child(8) .postags a {
    background-color:#19dada !important;
    color: #fff !important;
}
.retitle h2{margin:8px 0;display:block}
.post h2 a {      font: $(post.title.font);
  color: $(post.title.color);
    font-weight: 700;

    text-transform: uppercase;
    line-height: 1.2;}
.post h2 a:hover{color: $(post.title.color.hover);}
.post_author_date{color:#C4C4C4;font-size:13px;font-weight:400;line-height:23px;margin:0 0 25px;text-transform:uppercase}
.post_author{font-weight:600;margin-right:5px}
div.post_author_date a{text-decoration:none}
.resumo p{       margin: 0 0 10px;
    font-family: 'Domine';
    font-weight: 400;
    color: #444444;
    line-height: 30px;
    font-size: 16px;}

.resumo a{background-color:#171717;color:#fff!important;font-size:11px;font-weight:700;line-height:19px;display:inline-block;padding:0 6px}
.resumo a:hover{background-color:$(color.theme)}
.post .post-bottom {
    position: relative;
    font-size: 10px;
    padding: 10px 0 0;
    border-top: 1px dotted #E6E6E6;
}
.post .post-bottom .post-comment, .post .post-bottom .post-views {
    position: relative;
    display: inline-block;
    margin: 0 15px 0 0;
    text-transform: uppercase;
}

.post .post-bottom .post-comment a,.post .post-bottom .post-views {
    color: #B7B7B7;
    line-height: 1.42857143;
    -webkit-transition: all 0.35s ease-in-out;
    -moz-transition: all 0.35s ease-in-out;
    -ms-transition: all 0.35s ease-in-out;
    -o-transition: all 0.35s ease-in-out;
    transition: all 0.35s ease-in-out;
    font-family: 'Montserrat', sans-serif;
}

.post-views i, .post-comment a i {
    display: inline-block;
    margin: 0 1px 0 0;
}

.meta-border{display:block;width:60px;height:1px;background-color:#f0f0f0;margin:6px 0 10px}
.widget iframe,.widget img{max-width:100%}
.index .post-footer,.archive .post-footer{display:none!important}
.index .post h2,.archive .post h2{margin:0 0 8px;padding:0}
.item .post,.static_page .post{padding:0 0 25px}
.date-header{color:#222;display:block;font-size:12px;font-weight:400;line-height:1.3em;margin:0!important;padding:0}
.date-header a{color:#888}
.entry-meta {
      margin-top: 12px;
    font-size: 16px;
    color: #444444;
    margin-bottom: 30px;
}
 .meta-item {
    font-size: 13px;
    color: #888888;
   display: inline-table;
    vertical-align: top;
}

.meta-item a {
    text-decoration: none;
    padding-bottom: 3px;
    border-bottom: 1px solid transparent;
    -webkit-transition: border-bottom .1s ease-in-out;
    -o-transition: border-bottom .1s ease-in-out;
    transition: border-bottom .1s ease-in-out;
}

.meta-item a:hover {
border-bottom: 1px solid;
    color: #333333;
}
.meta-item {
    margin-right: 15px;
}

.meta-item:after {
    content: "/";
    right: -7px;
    position: relative;
}

.meta-item:last-child:after{display:none}

 .post-date {
    position: absolute;
    top: 8px;
    left: -40px;
    text-align: center;
    width: 75px;
}

.post-date-day{
    color: $(color.theme);
    display: block;
    font-size: 60px;
    line-height: 50px;
    font-family: 'Domine';
    font-weight: 400;
    text-align: center;
}

.post-date-month {
     color: #333333;
    font-family: 'Josefin Sans';
    font-weight: 700;
    font-size: 14px;
    line-height: 30px;
}

.entry-footer {
    margin-top: 30px;
}

.entry-footer .typology-button {
    margin-right: 15px;
}

.typology-button{
    height: 35px;
    display: inline-block;
    text-align: center;
    text-decoration: none;
    padding: 0 0px;
    line-height: 35px;
    min-width: 160px;
    font-size: 1.1rem;
    border: 1px solid;
    font-weight: 400;
    outline: 0;
    -ms-transform: translateY(0);
    -webkit-transform: translateY(0);
    transform: translateY(0);
    -webkit-transition: all .1s ease-in-out;
    -moz-transition: all .1s ease-in-out;
    -ms-transition: all .1s ease-in-out;
    -o-transition: all .1s ease-in-out;
    transition: all .1s ease-in-out;
    color: #ffffff!important;
    text-transform: uppercase;
    background: $(color.theme);
    border: 1px solid $(color.theme);
    font-family: 'Josefin Sans';
    font-weight: 700;
    font-size: 11px;
}

span.post-date-year {
    color: #333333;
    font-family: 'Josefin Sans';
    font-weight: 700;
    font-size: 14px;
    line-height: 30px;
}
.post-date:after {
    content: "";
    position: absolute;
    height: 11px;
    width: 11px;
    display: block;
    border-radius: 50%;
    left: 94px;
    top: 17px;
    z-index: 2;
}

.typology-button:hover {
    -webkit-box-shadow: 0 10px 20px 0 rgba(1,1,1,.15);
    box-shadow: 0 10px 20px 0 rgba(1,1,1,.15);
}

head.b:template-skin:
/*------Layout (No Edit)----------*/
